mcq(C, "l3dc-mcq1", [
    ("Que signifie le sigle OHADA ?", "Organisation pour l'harmonisation en Afrique du droit des affaires", ["Organisation hospitalière d'aide au développement en Afrique", "Office d'harmonisation des assurances et des douanes africaines", "Observatoire des hydrocarbures et des affaires diplomatiques d'Afrique"], "L'OHADA vise l'harmonisation du droit des affaires entre ses États parties.", 1),
    ("Quel est l'objectif principal de l'OHADA ?", "Harmoniser et moderniser le droit des affaires pour sécuriser l'activité économique", ["Créer une monnaie commune", "Instituer une armée commune", "Unifier le droit pénal et la procédure pénale de ses États", "Fixer les salaires minimaux des États"], "L'OHADA unifie le droit des affaires, non les autres branches du droit.", 2),
    ("Les Actes uniformes de l'OHADA sont-ils applicables dans les États parties sans transposition nationale ?", "Oui, ils sont directement applicables et obligatoires", ["Non, chaque État doit les transposer par une loi", "Non, ils ne s'appliquent qu'après un référendum dans chaque État", "Oui, mais seulement dans les entreprises publiques"], "Ils sont directement applicables et obligatoires dans les États parties.", 3),
    ("Que se passe-t-il en cas de contradiction entre un Acte uniforme et une loi nationale contraire ?", "L'Acte uniforme prévaut sur le droit interne contraire", ["La loi nationale prévaut toujours", "La plus récente des deux l'emporte", "Aucune n'est applicable"], "Les Actes uniformes l'emportent sur les dispositions contraires du droit interne, antérieures ou postérieures.", 4),
    ("Quelle institution de l'OHADA adopte les Actes uniformes ?", "Le Conseil des ministres", ["La Cour commune de justice et d'arbitrage", "L'ERSUMA", "Les tribunaux nationaux de commerce"], "Le Conseil des ministres de la justice et des finances adopte les Actes uniformes.", 3),
    ("Quelle institution de l'OHADA est chargée de l'interprétation commune des Actes uniformes ?", "La Cour commune de justice et d'arbitrage", ["Le Secrétariat permanent", "L'ERSUMA", "Le Conseil des ministres"], "La CCJA assure l'interprétation et l'application communes.", 3),
    ("Quel est le rôle de la CCJA comme juridiction ?", "Jouer le rôle de juridiction de cassation pour le contentieux des Actes uniformes", ["Juger en première instance tous les litiges commerciaux", "Juger les infractions pénales commises par les dirigeants", "Légiférer à la place des États"], "La CCJA statue sur les pourvois en cassation relatifs à l'application des Actes uniformes, hors sanctions pénales.", 4),
    ("De quelles juridictions relèvent les pourvois relatifs aux sanctions pénales prononcées en application des Actes uniformes ?", "Des juridictions nationales", ["De la CCJA exclusivement", "Du Conseil des ministres", "Du Secrétariat permanent"], "Les sanctions pénales restent de la compétence des États.", 5),
    ("Quelle est la double fonction de la CCJA ?", "Juridiction commune de cassation et institution d'arbitrage", ["Juridiction pénale et organe législatif", "Organe de contrôle des banques et tribunal du travail", "Organe de formation et juridiction fiscale"], "La CCJA est aussi un centre d'arbitrage.", 4),
    ("Dans l'arbitrage administré par la CCJA, que fait la Cour ?", "Nomme ou confirme les arbitres et examine les projets de sentence sans trancher elle-même le litige", ["Rend elle-même la sentence comme juge unique", "Se prononce seulement sur les crimes", "Remplace les arbitres choisis par les parties dans tous les cas"], "La CCJA administre l'arbitrage et contrôle les sentences, mais ne les rend pas.", 5),
    ("Quelle est la mission de l'ERSUMA ?", "Former et perfectionner les magistrats et les auxiliaires de justice", ["Juger les litiges commerciaux", "Adopter les Actes uniformes", "Tenir le registre du commerce"], "Elle contribue à la formation des praticiens du droit des affaires.", 3),
    ("Quel organe de l'OHADA est chargé de l'exécution et du suivi des travaux, notamment la préparation des projets d'Actes uniformes ?", "Le Secrétariat permanent", ["La Conférence des chefs d'État seule", "Le tribunal arbitral", "L'ERSUMA"], "Le Secrétariat permanent est l'organe exécutif de l'organisation.", 4),
    ("L'OHADA harmonise-t-elle le droit pénal général de ses États membres ?", "Non, elle ne vise que le droit des affaires", ["Oui, intégralement", "Oui, mais seulement en matière familiale", "Oui, mais seulement pour le droit foncier"], "Le champ de l'OHADA est le droit des affaires.", 3),
    ("Parmi ces matières, laquelle fait partie du droit des affaires harmonisé par l'OHADA ?", "Le droit des sociétés commerciales", ["Le droit de la famille", "Le droit constitutionnel", "Le droit électoral"], "Les sociétés commerciales font l'objet d'un Acte uniforme.", 2),
    ("Parmi ces matières, laquelle ne relève pas des Actes uniformes de l'OHADA ?", "Le droit des successions", ["Le droit des sûretés", "Les procédures collectives", "Le droit de l'arbitrage"], "Le droit des successions relève du droit civil national.", 3),
    ("Qu'est-ce qu'un commerçant en droit commercial général ?", "Une personne qui accomplit des actes de commerce et en fait sa profession habituelle", ["Toute personne qui achète un bien", "Toute personne qui possède un local", "Toute personne qui signe un contrat de travail"], "La profession habituelle est essentielle : un acte isolé ne suffit pas.", 1),
    ("Un particulier qui achète une seule fois une marchandise pour la revendre avec profit devient-il commerçant par cet acte isolé ?", "Non, il lui manque la profession habituelle", ["Oui, immédiatement", "Oui, s'il a un diplôme", "Oui, si le montant est élevé"], "La qualité de commerçant suppose l'accomplissement habituel d'actes de commerce à titre de profession.", 4),
    ("Quelles personnes peuvent avoir la qualité de commerçant ?", "Les personnes physiques et les sociétés commerciales", ["Les personnes physiques seulement", "Les États seulement", "Les associations à but non lucratif seulement"], "Les sociétés commerciales ont la qualité de commerçant par leur forme.", 3),
    ("Un mineur non émancipé peut-il, en principe, être commerçant ?", "Non, la capacité commerciale lui fait défaut", ["Oui, dès la naissance", "Oui, avec le seul accord d'un camarade", "Oui, s'il possède un local"], "Le mineur, sauf émancipé, ne peut avoir la qualité de commerçant.", 3),
    ("Qu'est-ce qu'une incompatibilité avec l'exercice du commerce ?", "L'interdiction d'exercer le commerce attachée à certaines fonctions ou professions", ["L'obligation de tenir une comptabilité", "L'inscription au registre du commerce", "L'obligation de payer des dividendes"], "Certaines fonctions, comme celle de fonctionnaire, sont incompatibles avec la profession commerciale.", 3),
    ("Laquelle de ces personnes est, en principe, soumise à une incompatibilité avec l'exercice de la profession commerciale ?", "Un fonctionnaire", ["Un artisan", "Un marchand ambulant", "Un grossiste"], "Les agents publics ne peuvent en principe cumuler leur fonction avec une activité commerciale.", 3),
    ("Quelle différence existe-t-il entre incompatibilité et interdiction d'exercer le commerce ?", "L'incompatibilité tient à une fonction exercée, l'interdiction à une sanction", ["L'incompatibilité est volontaire, l'interdiction est facultative", "Il n'y a aucune différence", "L'incompatibilité concerne les sociétés, l'interdiction les personnes physiques"], "L'une protège l'indépendance d'une fonction, l'autre sanctionne un comportement.", 5),
    ("Quelle obligation pèse sur tout commerçant ?", "S'immatriculer au registre du commerce et du crédit mobilier", ["Verser un dividende", "Faire un arbitrage chaque année", "Désigner un commissaire aux comptes dans tous les cas"], "L'immatriculation au RCCM est une obligation du commerçant.", 2),
    ("Quelle est l'utilité du RCCM pour les tiers ?", "Assurer la publicité des informations légales sur les commerçants et les sociétés", ["Garantir que les commerçants ne feront jamais faillite", "Fixer le prix des marchandises", "Désigner les administrateurs des sociétés"], "Le registre informe les tiers de la situation des commerçants.", 2),
    ("À quel moment une société commerciale acquiert-elle en principe la personnalité morale en droit OHADA ?", "À son immatriculation au registre du commerce et du crédit mobilier", ["À la signature du bail de ses locaux", "À la première assemblée générale", "À l'ouverture d'un compte bancaire"], "L'immatriculation donne naissance à la personne morale.", 4),
    ("Que peut-on aussi inscrire au RCCM, outre l'immatriculation des commerçants ?", "Certaines sûretés mobilières", ["Les mariages des commerçants", "Les décisions pénales de tout citoyen", "Les naissances des associés"], "Le « crédit mobilier » désigne l'inscription des sûretés mobilières.", 4),
    ("Quels sont les trois types d'actes de commerce habituellement distingués ?", "Par nature, par la forme et par accessoire", ["Par écrit, par oral et par geste", "Par la loi, par la coutume et par le juge", "Par l'État, par les sociétés et par les particuliers"], "Cette classification est classique en droit commercial.", 2),
    ("Qu'est-ce qu'un acte de commerce par nature ?", "Un acte qui est commercial en raison de son objet, quel que soit celui qui l'accomplit", ["Un acte commercial uniquement parce qu'il est signé", "Un acte accompli uniquement par un commerçant", "Un acte accompli sans contrat"], "Achat pour revendre, opérations de banque, etc.", 3),
    ("Qu'est-ce qu'un acte de commerce par la forme ?", "Un acte commercial en raison de sa forme, quelle que soit sa cause, comme la lettre de change", ["Un acte commercial parce qu'il est accompli par un étranger", "Un acte commercial parce qu'il est verbal", "Un acte commercial parce qu'il est notarié"], "La forme suffit, indépendamment de l'objet ou de la qualité de l'auteur.", 4),
    ("Qu'est-ce qu'un acte de commerce par accessoire ?", "Un acte civil par nature devenant commercial parce qu'il est lié à l'exercice d'un commerce", ["Un acte commercial qui n'a pas d'importance", "Un acte accompli à titre gratuit", "Un acte administratif"], "Les actes accomplis par le commerçant pour les besoins de son commerce suivent le régime commercial.", 4),
    ("Un commerçant achète un véhicule pour la livraison de ses clients. Quelle est la nature de cet acte ?", "Un acte de commerce par accessoire", ["Un acte de commerce par la forme", "Un acte purement civil sans lien avec le commerce", "Un acte administratif"], "L'achat est lié aux besoins de son commerce.", 3),
    ("Un acte peut-il être civil pour l'une des parties et commercial pour l'autre ?", "Oui, c'est un acte mixte", ["Non, jamais", "Oui, mais uniquement entre commerçants", "Oui, mais uniquement en droit pénal"], "L'acte mixte est commercial pour une partie, civil pour l'autre.", 4),
    ("Quelle est la règle de preuve traditionnelle en matière commerciale ?", "En droit commercial classique, la preuve est libre", ["La preuve est toujours écrite", "La preuve est toujours testimoniale", "La preuve exige un notaire"], "La liberté de preuve est un trait du droit commercial.", 3),
    ("En quoi la liberté de la preuve est-elle utile au commerce ?", "Elle favorise la rapidité des affaires en évitant de multiplier les formalités", ["Elle remplace le contrat par une loi", "Elle supprime les tribunaux", "Elle interdit tout écrit"], "Le droit commercial privilégie la rapidité et la souplesse.", 3),
    ("De quels éléments, au minimum, un fonds de commerce comprend-il nécessairement en droit OHADA ?", "La clientèle et l'enseigne ou le nom commercial", ["Le matériel et les marchandises", "Le droit au bail et les brevets", "Les marques et les contrats de travail"], "Sans clientèle ni signe distinctif, il n'y a pas de fonds de commerce.", 5),
    ("Lequel de ces éléments est un élément incorporel du fonds de commerce ?", "Le nom commercial", ["Un camion de livraison", "Le stock de marchandises", "Une table du magasin"], "Le nom commercial est un bien immatériel.", 2),
    ("Lequel de ces éléments est un élément corporel d'un fonds de commerce ?", "Le matériel d'exploitation", ["La clientèle", "L'enseigne", "Le droit au bail"], "Le matériel est un bien matériel.", 2),
    ("La clientèle est-elle un bien que l'on peut transmettre librement comme un meuble ?", "Non, elle est attachée au fonds et ne se transmet qu'avec lui", ["Oui, elle se vend isolément", "Oui, par simple remise de main à main", "Oui, par donation seulement"], "La clientèle fait partie du fonds et suit son sort.", 4),
    ("Quel est l'intérêt de l'écrit dans la vente d'un fonds de commerce ?", "Il assure la preuve et permet l'accomplissement des formalités de publicité", ["Il est interdit", "Il rend le fonds inaliénable", "Il supprime l'immatriculation"], "La vente d'un fonds est entourée de formalités destinées à protéger les créanciers.", 4),
    ("Qu'est-ce que le nantissement du fonds de commerce ?", "Une sûreté réelle sans dépossession portant sur le fonds", ["Une vente définitive du fonds", "Un mandat d'administration du fonds", "Un bail du local commercial"], "Le fonds reste exploité par son propriétaire tout en garantissant le créancier.", 4),
    ("Qu'est-ce que la location-gérance ?", "La mise à disposition de l'exploitation d'un fonds à un gérant contre redevance", ["La vente du fonds", "La fermeture du fonds", "La liquidation du fonds"], "Le propriétaire reste propriétaire mais ne l'exploite plus.", 4),
    ("Dans une location-gérance, qui exploite le fonds à ses risques et périls ?", "Le locataire-gérant", ["Le propriétaire du fonds", "Le bailleur du local", "L'État"], "Le locataire-gérant exploite à ses risques et périls et a la qualité de commerçant.", 5),
    ("Quelle est la qualité du locataire-gérant ?", "Il est commerçant", ["Il est salarié du propriétaire", "Il est associé du propriétaire", "Il est fonctionnaire"], "Il exploite pour son propre compte.", 4),
    ("Qu'est-ce qu'un bail commercial, en principe ?", "Un contrat de location d'un immeuble où s'exerce une activité commerciale", ["Un contrat de vente d'un immeuble", "Un contrat de prêt d'argent", "Un contrat de travail entre locataire et bailleur"], "Il protège l'exploitant du fonds.", 2),
    ("Pourquoi le droit commercial protège-t-il particulièrement le locataire d'un local commercial ?", "Parce que la valeur du fonds dépend en grande partie de l'emplacement du local", ["Parce que les locataires sont toujours pauvres", "Parce que la loi interdit les loyers", "Parce que le bailleur est toujours l'État"], "La stabilité du lieu conditionne la clientèle.", 3),
    ("Quel droit essentiel est reconnu au locataire commerçant en principe, à l'expiration du bail ?", "Le droit au renouvellement du bail", ["Le droit d'acquérir gratuitement l'immeuble", "Le droit de ne plus payer de loyer", "Le droit de louer à qui il veut sans limite"], "Il protège la pérennité de l'exploitation.", 3),
    ("Que doit en principe le bailleur qui refuse le renouvellement du bail commercial sans motif légitime ?", "Payer une indemnité d'éviction au locataire", ["Verser une dette fiscale", "Remettre l'immeuble à l'État", "Payer le loyer à la place du locataire"], "L'indemnité compense la perte du fonds liée à l'éviction.", 5),
    ("Le preneur à bail commercial peut-il, en principe, céder son bail avec son fonds ?", "Oui, la cession du bail accompagne la cession du fonds", ["Non, jamais", "Oui, mais seulement à ses descendants", "Oui, mais seulement après dissolution"], "Le droit au bail est un élément du fonds.", 4),
    ("Quelle est la nature du contrat de vente commerciale ?", "Un contrat où le vendeur transfère la propriété d'une marchandise contre un prix", ["Un contrat de travail", "Un contrat de société", "Un contrat de prêt à usage"], "La vente suppose chose, prix et consentement.", 2),
    ("Quelle est l'obligation principale du vendeur dans une vente commerciale ?", "Délivrer une marchandise conforme et transférer la propriété", ["Payer le prix", "Garantir que l'acheteur sera commerçant", "Assurer l'acheteur contre toute perte de la marchandise"], "Le vendeur doit livrer et transférer la propriété.", 2),
    ("Quelle est l'obligation principale de l'acheteur dans une vente commerciale ?", "Payer le prix et prendre livraison de la marchandise", ["Fournir la marchandise", "Inscrire le vendeur au registre du commerce", "Garantir la clientèle du vendeur"], "Il doit payer et recevoir les marchandises.", 2),
    ("Qu'est-ce que la garantie de conformité de la marchandise ?", "L'obligation du vendeur de livrer une marchandise conforme à ce qui est prévu au contrat", ["L'obligation de l'acheteur de la revendre", "L'obligation du transporteur de la conserver", "L'obligation de l'État de la contrôler"], "La conformité vise la quantité, la qualité et la description.", 3),
    ("La vente commerciale règle-t-elle, en principe, la vente aux consommateurs ?", "Non, elle vise les ventes entre professionnels", ["Oui, exclusivement", "Oui, uniquement pour les ventes d'immeubles", "Oui, pour les successions"], "Le régime de la vente commerciale s'adresse aux opérations professionnelles.", 5),
    ("Qu'est-ce que la concurrence déloyale ?", "L'usage de procédés contraires aux usages honnêtes pour détourner la clientèle d'un concurrent", ["La simple existence de concurrents", "La fixation d'un prix bas conforme aux règles", "La création d'un nouveau commerce"], "La libre concurrence reste le principe ; les procédés déloyaux sont sanctionnés.", 3),
    ("Parmi ces comportements, lequel constitue un acte de concurrence déloyale ?", "Créer volontairement la confusion avec les produits d'un concurrent", ["Baisser ses prix en respectant la loi", "Améliorer la qualité de ses produits", "Faire de la publicité exacte"], "La confusion trompe la clientèle et détourne son choix.", 3),
    ("Quelle sanction frappe en principe la concurrence déloyale ?", "L'engagement de la responsabilité civile de son auteur", ["La prison automatique", "La dissolution des tous les concurrents", "La suppression de la profession commerciale"], "Le concurrent lésé obtient la cessation du trouble et des dommages-intérêts.", 4),
    ("Que signifie la liberté du commerce et de l'industrie ?", "Chacun est libre d'exercer l'activité commerciale de son choix dans le respect de la loi", ["Seuls les nationaux peuvent commercer", "L'État décide qui peut commercer", "Le commerce est exclusivement réservé aux sociétés"], "C'est un principe fondamental du droit commercial.", 3),
    ("Quelle est la différence essentielle entre un commissionnaire et un mandataire ?", "Le commissionnaire agit en son nom propre, le mandataire au nom de son mandant", ["Le commissionnaire agit au nom du mandant, le mandataire en son nom propre", "Ils agissent tous deux sous le nom du tiers seulement", "Ils agissent tous deux sans aucun pouvoir"], "La représentation est directe pour le mandataire, indirecte pour le commissionnaire.", 5),
    ("Un courtier est-il partie au contrat qu'il a contribué à conclure ?", "Non, il se limite à rapprocher les parties", ["Oui, il est toujours partie", "Oui, comme garant", "Oui, comme acheteur"], "Le courtier met en relation sans contracter lui-même.", 3),
    ("Un agent commercial agit-il en son nom ou au nom de son mandant ?", "Au nom et pour le compte de son mandant", ["En son nom propre et pour le compte d'un tiers inconnu", "En son nom et pour son compte", "Au nom de l'État"], "L'agent commercial est un mandataire.", 4),
    ("Que doit faire un commerçant pour être en règle sur l'obligation comptable, de façon générale ?", "Tenir une comptabilité régulière selon les règles applicables", ["Employer un comptable salarié", "Verser la moitié de ses bénéfices à l'État", "Fermer son commerce chaque année"], "La tenue d'une comptabilité fait partie des obligations du commerçant.", 3),
    ("Que doit faire un commerçant en matière de comptes à la fin de l'exercice ?", "Établir des états financiers annuels", ["Dissoudre l'entreprise", "Payer des dividendes à ses clients", "Désigner un arbitre"], "Les comptes annuels retracent la situation de l'entreprise.", 2),
    ("Qu'est-ce que la publicité légale des sociétés ?", "La diffusion d'informations officielles pour informer les tiers sur la société", ["La campagne de promotion de ses produits", "Un contrat avec un journal", "Une garantie bancaire"], "Elle protège les tiers qui contractent avec la société.", 3),
    ("Qu'est-ce que l'entreprenant dans le droit OHADA ?", "Un entrepreneur individuel qui exerce une petite activité sous un régime simplifié, sur déclaration", ["Une société à capital variable", "Un commerçant ayant fait faillite", "Un salarié créateur d'entreprise"], "Le statut vise à simplifier la formalisation des petites activités.", 4),
    ("Le statut d'entreprenant permet-il d'exercer des activités uniquement commerciales ?", "Non, il couvre aussi des activités civiles, artisanales ou agricoles", ["Oui, uniquement commerciales", "Oui, uniquement agricoles", "Oui, uniquement industrielles"], "Il concerne l'entrepreneur individuel de petite taille quelle que soit la nature de l'activité.", 5),
    ("En quoi la société en participation se distingue-t-elle des autres sociétés commerciales ?", "Elle n'a pas la personnalité morale et n'est pas immatriculée", ["Elle est toujours cotée en bourse", "Elle est toujours une société anonyme", "Elle est la seule à avoir un capital"], "C'est une société occulte, sans personnalité juridique.", 4),
    ("Qui peut avoir la qualité de société commerciale par la forme en droit OHADA ?", "La SNC, la SCS, la SARL et la SA, quel que soit leur objet", ["Seulement les sociétés qui vendent des marchandises", "Seulement les sociétés publiques", "Seulement les groupements d'intérêt économique"], "La forme emporte la commercialité, quel que soit l'objet.", 5),
    ("Qu'est-ce que le contrat de société ?", "Un contrat où des personnes mettent des apports en commun pour partager les résultats", ["Un contrat de vente d'immeuble", "Un contrat de prêt à intérêt", "Un contrat de travail collectif"], "Apport, partage des résultats et intention de s'associer le caractérisent.", 3),
    ("Quels sont les éléments constitutifs du contrat de société, de façon générale ?", "Les apports, la participation aux résultats et l'affectio societatis", ["Le salaire, le préavis et la subordination", "Le prix, la chose et la livraison", "La clause pénale, le terme et le cautionnement"], "Ces éléments distinguent la société des autres contrats.", 3),
    ("Qu'est-ce que la clause léonine ?", "La clause qui attribue à un associé la totalité des profits ou l'exonère de toute perte", ["La clause qui limite la durée de la société", "La clause qui fixe le siège social", "La clause qui désigne le gérant"], "Elle est réputée non écrite car contraire à l'essence du contrat de société.", 5),
    ("Quel est l'effet de la personnalité morale d'une société ?", "Elle a un patrimoine distinct de celui des associés", ["Elle fusionne le patrimoine des associés", "Elle empêche tout contrat", "Elle supprime le capital"], "Le patrimoine de la société est distinct de celui des associés.", 3),
], cat=K, src="sup-comm", region="AF")

mcq(C, "l3dc-mcq2", [
    ("Quelle est la responsabilité des associés d'une société en nom collectif pour les dettes sociales ?", "Indéfinie et solidaire", ["Limitée au montant des apports", "Nulle dans tous les cas", "Limitée à une somme fixée par le tribunal"], "Les associés en nom collectif répondent indéfiniment et solidairement des dettes de la société.", 2),
    ("Quelle est la qualité des associés d'une société en nom collectif ?", "Ils ont tous la qualité de commerçant", ["Ils sont tous salariés de la société", "Ils sont tous fonctionnaires", "Ils sont tous des mineurs"], "L'associé en nom collectif est commerçant.", 3),
    ("Dans une société en commandite simple, quelle est la situation du commanditaire ?", "Il est tenu des dettes sociales seulement à hauteur de son apport", ["Il est tenu indéfiniment et solidairement", "Il ne participe pas aux bénéfices", "Il gère nécessairement la société"], "La limitation de responsabilité du commanditaire a pour contrepartie son exclusion de la gestion externe.", 3),
    ("Dans une société en commandite simple, qui répond indéfiniment et solidairement des dettes sociales ?", "Les commandités", ["Les commanditaires", "Les salariés", "Les créanciers"], "Les commandités ont le statut d'associés en nom collectif.", 3),
    ("Pourquoi le commanditaire ne doit-il pas, en principe, accomplir d'actes de gestion externe ?", "Pour ne pas perdre le bénéfice de sa responsabilité limitée", ["Parce qu'il est mineur", "Parce qu'il est salarié", "Parce que la loi interdit tout apport"], "S'il s'immisce dans la gestion externe, il peut être tenu comme un commandité envers les tiers.", 5),
    ("Quelle est la responsabilité des associés d'une SARL pour les dettes sociales ?", "Limitée au montant de leurs apports", ["Indéfinie et solidaire", "Illimitée pour le gérant seulement", "Exclusivement subsidiaire sur leurs biens personnels"], "Le principe de la limitation des pertes aux apports caractérise la SARL.", 2),
    ("Comment appelle-t-on les titres représentatifs du capital d'une SARL ?", "Des parts sociales", ["Des actions", "Des obligations", "Des warrants"], "La SARL a un capital divisé en parts sociales.", 2),
    ("Comment appelle-t-on les titres représentatifs du capital d'une société anonyme ?", "Des actions", ["Des parts sociales", "Des lettres de change", "Des billets à ordre"], "Les actions sont les titres de capital de la société anonyme.", 2),
    ("Quelle est la différence essentielle entre action et obligation ?", "L'action est un titre de capital, l'obligation un titre de créance", ["L'action est un titre de créance, l'obligation un titre de capital", "Ce sont deux titres de capital", "Ce sont deux titres d'État"], "L'actionnaire est associé, l'obligataire est créancier.", 4),
    ("Qui dirige une SARL ?", "Un ou plusieurs gérants", ["Un commissaire aux comptes", "Un huissier de justice", "Un conciliateur"], "Le gérant est l'organe de direction de la SARL.", 2),
    ("Qui est le principal organe de décision collective des associés ?", "L'assemblée générale ou la décision collective des associés", ["Le tribunal de commerce", "Le greffier", "L'huissier"], "Les associés décident collectivement des questions importantes.", 2),
    ("Quel est le rôle du conseil d'administration dans une société anonyme ?", "Déterminer les orientations de la société et contrôler la direction", ["Juger les litiges avec les clients", "Tenir le registre du commerce", "Exécuter les saisies"], "Le conseil d'administration est l'organe collégial de direction de la société anonyme.", 3),
    ("Qui représente la société anonyme à l'égard des tiers lorsque la direction est confiée au président-directeur général ?", "Le président-directeur général", ["Le commissaire aux comptes", "L'actionnaire le plus âgé", "Le greffier du tribunal"], "Le PDG cumule la présidence du conseil et la direction générale.", 4),
    ("Que fait le commissaire aux comptes dans une société ?", "Il contrôle les comptes et certifie leur régularité et leur sincérité", ["Il dirige la société", "Il fixe le prix des produits", "Il représente les associés devant le juge"], "Il est indépendant de la direction.", 3),
    ("Pourquoi le commissaire aux comptes doit-il être indépendant ?", "Pour garantir l'objectivité de sa certification", ["Pour toucher une rémunération plus élevée", "Pour siéger au conseil d'administration", "Pour gérer la société à la place du gérant"], "Son rôle suppose l'absence de lien de subordination avec la direction.", 4),
    ("Qu'est-ce que l'apport en industrie ?", "Un apport de travail ou de savoir-faire qui ne contribue pas à la formation du capital social", ["Un apport d'argent entrant dans le capital", "Un apport d'un immeuble entrant dans le capital", "Un apport de marchandises"], "Seuls les apports en numéraire et en nature forment le capital social.", 5),
    ("Quelle différence entre apport en numéraire et apport en nature ?", "Le premier est de l'argent, le second est un bien autre que l'argent", ["Le premier est un travail, le second un bien", "Le premier est un immeuble, le second un service", "Il n'y a aucune différence"], "Le numéraire est une somme d'argent ; la nature, un bien.", 2),
    ("Que doit-on vérifier en principe lorsqu'un associé fait un apport en nature ?", "Que le bien apporté est correctement évalué", ["Que l'associé est le plus âgé", "Que le bien est neuf", "Que l'apport est effectué en dehors du siège"], "L'évaluation protège les tiers et les autres associés.", 4),
    ("Qu'est-ce que le capital social, par rapport aux bénéfices ?", "Un montant fixé par les statuts correspondant aux apports, distinct des résultats", ["Le montant des bénéfices distribués", "Le montant des dettes de la société", "Le montant des impôts payés"], "Le capital est formé des apports ; les bénéfices en sont distincts.", 3),
    ("Que protège la règle du capital social vis-à-vis des créanciers ?", "Il constitue en principe un gage minimal de leurs créances", ["Il garantit qu'ils seront toujours payés", "Il permet d'éviter toute faillite", "Il remplace le registre du commerce"], "Le capital est un gage, non une garantie absolue.", 4),
    ("Que sont les dividendes ?", "Des sommes prélevées sur les bénéfices et distribuées aux associés", ["Des sommes prélevées sur les dettes", "Des impôts dus à l'État", "Des salaires des dirigeants"], "Ils rémunèrent l'apport des associés.", 2),
    ("Peut-on distribuer des dividendes en l'absence de bénéfice distribuable ?", "Non, la distribution de dividendes fictifs est prohibée", ["Oui, librement", "Oui, si le gérant le décide seul", "Oui, si le commissaire aux comptes le décide"], "Les dividendes fictifs lèsent les créanciers.", 4),
    ("Qu'est-ce que la réserve légale ?", "Un prélèvement obligatoire sur les bénéfices destiné à renforcer la situation de la société", ["Un impôt sur le capital", "Un dividende privilégié", "Une subvention de l'État"], "Elle consolide les fonds propres.", 4),
    ("Que signifie l'affectio societatis ?", "La volonté de s'associer et de collaborer à l'œuvre commune", ["Le droit de licencier les associés", "La garantie bancaire de la société", "L'obligation de souscrire des actions"], "C'est un élément psychologique du contrat de société.", 4),
    ("Quelle est la conséquence de la personnalité morale d'une société sur ses dettes ?", "La société, et non les associés personnellement, est en principe débitrice", ["Les associés sont toujours seuls débiteurs", "Le gérant est toujours seul débiteur", "L'État est débiteur"], "Le patrimoine social répond des dettes de la société.", 3),
    ("Que signifie l'expression « responsabilité limitée » pour un associé ?", "Il ne peut perdre, en principe, que ce qu'il a apporté", ["Il ne répond de rien en aucun cas", "Il répond seulement à l'égard du gérant", "Il répond sur tous ses biens"], "La perte maximale est le montant de l'apport.", 2),
    ("Dans quel cas la responsabilité limitée d'un associé de SARL peut-elle être remise en cause ?", "En cas de fraude ou de faute personnelle de gestion reconnue", ["Quand il siège à l'assemblée", "Quand il détient des parts", "Quand il vote sur les comptes"], "La limitation ne protège pas contre ses propres fautes.", 5),
    ("Qu'est-ce qu'un groupement d'intérêt économique, de façon générale ?", "Un groupement de personnes qui mettent des moyens en commun pour faciliter leur activité économique", ["Une société cotée en bourse", "Une société à capital obligatoirement très élevé", "Une société de gestion de patrimoine"], "Le GIE sert à faciliter ou développer l'activité de ses membres.", 4),
    ("Un GIE a-t-il pour but de réaliser des bénéfices pour lui-même ?", "Non, son but est de faciliter l'activité de ses membres", ["Oui, exclusivement", "Oui, uniquement pour les membres étrangers", "Oui, uniquement après dissolution"], "Il n'est pas créé pour réaliser des bénéfices pour lui-même.", 4),
    ("Quelle est la responsabilité des membres d'un GIE à l'égard des dettes du groupement ?", "Indéfinie et solidaire", ["Limitée à l'apport", "Nulle", "Limitée aux dividendes reçus"], "Les membres du GIE répondent indéfiniment et solidairement de ses dettes.", 5),
    ("Qu'est-ce qu'une société commerciale par la forme ?", "Une société qui est commerciale en raison de sa forme, quel que soit son objet", ["Une société qui vend uniquement des marchandises", "Une société sans associés", "Une société sans dirigeant"], "La forme emporte commercialité.", 4),
    ("Laquelle de ces formes de société est toujours commerciale par sa forme en droit OHADA ?", "La société anonyme", ["La société civile", "L'association", "Le syndicat professionnel"], "La société anonyme est commerciale par sa forme.", 4),
    ("Laquelle de ces sociétés est de type société de capitaux ?", "La société anonyme", ["La société en nom collectif", "La société en participation", "La société de fait"], "Elle repose sur les capitaux plutôt que sur la personne des associés.", 3),
    ("Laquelle de ces sociétés est de type société de personnes ?", "La société en nom collectif", ["La société anonyme", "La société cotée", "La société d'investissement"], "Elle repose sur la personne des associés.", 3),
    ("Qu'appelle-t-on dissolution d'une société ?", "L'événement ou la décision qui met fin à la société et ouvre la liquidation", ["La vente d'une action", "La nomination d'un gérant", "La tenue d'une assemblée"], "La liquidation suit la dissolution.", 3),
    ("Quelle opération suit la dissolution d'une société ?", "La liquidation", ["La constitution", "L'immatriculation", "La cession d'actions"], "La liquidation règle les dettes et répartit l'actif.", 3),
    ("La société subsiste-t-elle après sa dissolution ?", "Oui, pour les besoins de la liquidation", ["Non, elle disparaît immédiatement", "Non, mais ses associés restent solidaires", "Oui, comme si rien n'avait changé"], "La personnalité morale subsiste pour les besoins de la liquidation.", 5),
    ("Qui est chargé de réaliser la liquidation de la société ?", "Le liquidateur", ["Le commissaire aux comptes", "Le conseil des ministres", "Le greffier"], "Le liquidateur règle les dettes et répartit l'actif net.", 3),
    ("Qu'est-ce qu'une fusion de sociétés ?", "L'opération par laquelle des sociétés s'unissent en une seule", ["La dissolution sans liquidation d'une seule société", "L'achat d'un fonds par un particulier", "La division d'une dette"], "La société absorbante ou nouvelle reprend les patrimoines.", 3),
    ("Qu'est-ce que la cession de parts sociales ?", "Le transfert à un tiers ou à un associé de la propriété de parts sociales", ["La création de nouvelles parts", "Le remboursement du capital", "La dissolution de la société"], "Elle transmet la qualité d'associé.", 3),
    ("Pourquoi la cession de parts d'une SARL à un tiers est-elle souvent encadrée ?", "Parce que les associés tiennent à choisir les personnes avec lesquelles ils s'associent", ["Parce que les parts n'ont aucune valeur", "Parce que l'État fixe leur prix", "Parce que le notaire est obligé d'acheter"], "La SARL a une dimension de personne qui justifie un contrôle de l'entrée de tiers.", 5),
    ("Qu'est-ce que la lettre de change ?", "Un écrit par lequel le tireur ordonne au tiré de payer une somme à un bénéficiaire", ["Une promesse du débiteur de payer son propre créancier", "Un contrat de location", "Un titre de capital"], "La lettre de change est un ordre de payer ; le billet à ordre, une promesse.", 2),
    ("Quelles personnes interviennent à l'origine dans une lettre de change ?", "Le tireur, le tiré et le bénéficiaire", ["Le souscripteur et le bénéficiaire seulement", "Le tireur seul", "Le porteur et le greffier"], "Trois rôles distincts interviennent.", 2),
    ("Quelles personnes interviennent à l'origine dans un billet à ordre ?", "Le souscripteur et le bénéficiaire", ["Le tireur, le tiré et le bénéficiaire", "Le tiré seul", "Le porteur et le greffier"], "Le souscripteur promet de payer au bénéficiaire.", 2),
    ("Quelle est la différence essentielle entre lettre de change et billet à ordre ?", "La lettre de change est un ordre de payer, le billet à ordre est une promesse de payer", ["La lettre de change est une promesse, le billet un ordre", "Il n'y a aucune différence", "La lettre est un titre d'État, le billet un titre privé"], "L'un est un ordre adressé à un tiers, l'autre un engagement personnel.", 3),
    ("Qui est le tiré dans une lettre de change ?", "La personne à qui l'ordre de payer est adressé", ["La personne qui émet la lettre", "La personne qui reçoit le paiement", "La personne qui garantit le paiement"], "Le tiré est le débiteur désigné.", 2),
    ("Qui est le tireur d'une lettre de change ?", "La personne qui émet la lettre et donne l'ordre de payer", ["La personne qui paie", "La personne qui reçoit la somme", "La personne qui protête la lettre"], "Le tireur crée la lettre.", 2),
    ("Que signifie accepter une lettre de change ?", "S'engager, pour le tiré, à la payer à l'échéance", ["La refuser", "La transmettre", "La détruire"], "L'acceptation oblige le tiré envers le porteur.", 3),
    ("Quel effet l'acceptation a-t-elle sur le tiré ?", "Il devient le débiteur principal de la lettre", ["Il n'est plus obligé", "Il devient tireur", "Il devient bénéficiaire"], "L'accepteur est tenu au paiement.", 4),
    ("Qu'est-ce que l'endossement ?", "La transmission d'un effet de commerce au moyen d'une mention signée sur le titre", ["La destruction de l'effet", "Le paiement de l'effet", "Le protêt de l'effet"], "L'endossement transfère la créance.", 3),
    ("Quel est l'effet principal de l'endossement ?", "Transférer la propriété de la créance à l'endossataire", ["Éteindre la créance", "Annuler l'effet", "Empêcher tout paiement"], "L'effet est transmis, et l'endosseur devient garant du paiement.", 4),
    ("Que garantit en principe l'endosseur d'une lettre de change ?", "Le paiement de la lettre au porteur", ["Rien du tout", "Seulement la date de l'échéance", "Seulement l'identité du tiré"], "L'endosseur est garant de l'acceptation et du paiement.", 5),
    ("Qu'est-ce que l'aval ?", "La garantie du paiement d'un effet de commerce donnée par une personne", ["La destruction de l'effet", "La date d'échéance de l'effet", "L'acceptation par le tiré"], "L'avaliste s'engage comme celui qu'il garantit.", 4),
    ("Quelle est la différence entre cautionnement et aval ?", "L'aval est donné sur un effet de commerce et rend l'avaliste tenu de façon autonome", ["L'aval est donné sur un immeuble", "Le cautionnement est donné sur un effet de commerce", "Il n'y a aucune différence"], "L'aval est une garantie propre aux effets de commerce, au régime plus rigoureux.", 5),
    ("Qu'est-ce que le protêt ?", "L'acte qui constate officiellement le défaut d'acceptation ou de paiement d'un effet", ["Le paiement de l'effet", "L'endossement de l'effet", "L'acceptation de l'effet"], "Il conserve les recours du porteur contre les signataires.", 4),
    ("Quel professionnel établit en général le protêt ?", "L'huissier de justice", ["Le commissaire aux comptes", "Le conciliateur", "Le syndic"], "L'huissier établit les actes de constatation.", 4),
    ("Qu'est-ce que l'échéance d'un effet de commerce ?", "La date à laquelle il doit être payé", ["La date de sa création", "La date de son endossement", "La date de son aval"], "Le paiement doit avoir lieu à l'échéance.", 2),
    ("Qu'est-ce que la provision dans une lettre de change ?", "La créance du tireur sur le tiré, qui permet le paiement à l'échéance", ["Un prélèvement de la banque", "Une taxe de l'État", "Une peine du juge"], "Sans provision, le tiré n'a pas de motif de payer pour le compte du tireur.", 4),
    ("Qu'est-ce qu'un chèque ?", "Un écrit par lequel le tireur ordonne à sa banque de payer une somme à vue", ["Un ordre de payer à une date convenue", "Une promesse de payer à terme", "Un titre de propriété"], "Il est payable à vue.", 2),
    ("Qui est le tiré d'un chèque ?", "Le banquier du tireur", ["Le bénéficiaire", "Le tireur", "L'huissier"], "Le tiré est la banque qui détient le compte.", 2),
    ("Que signifie « payable à vue » pour un chèque ?", "Il doit être payé dès sa présentation", ["Il doit être payé dans une longue période", "Il ne peut jamais être payé", "Il doit être payé par un tiers"], "Le chèque est un instrument de paiement, non de crédit.", 3),
    ("Quelle différence y a-t-il entre chèque et lettre de change du point de vue de la fonction ?", "Le chèque est un instrument de paiement, la lettre de change peut être un instrument de crédit", ["Le chèque est un instrument de crédit, la lettre un instrument de paiement immédiat", "Ce sont deux instruments de crédit", "Ce sont deux titres de capital"], "L'échéance de la lettre permet un crédit entre les parties.", 4),
    ("Qu'est-ce qu'un chèque barré ?", "Un chèque qui ne peut être payé qu'à un banquier ou à un client du banquier tiré", ["Un chèque périmé", "Un chèque falsifié", "Un chèque refusé"], "Le barrement limite les risques en cas de vol.", 4),
    ("Qu'est-ce qu'un chèque sans provision ?", "Un chèque émis alors que le compte ne contient pas les fonds nécessaires pour le payer", ["Un chèque émis par un mineur", "Un chèque non signé", "Un chèque endossé"], "Le défaut de provision peut être sanctionné.", 3),
    ("Un effet de commerce est-il, en principe, un titre transmissible ?", "Oui, il peut circuler par endossement", ["Non, jamais", "Oui, mais uniquement par décision du juge", "Oui, mais uniquement par acte notarié"], "L'endossement permet la circulation de l'effet.", 3),
    ("Quel principe protège le porteur de bonne foi d'un effet de commerce ?", "L'inopposabilité des exceptions fondées sur les rapports antérieurs entre signataires", ["La gratuité du titre", "L'interdiction de toute circulation", "L'obligation d'accepter tout effet"], "Cette règle renforce la sécurité des échanges.", 5),
    ("Quelles sont les mentions essentielles d'une lettre de change ?", "Notamment la dénomination, l'ordre de payer, le nom du tiré et la signature du tireur", ["Uniquement le nom du bénéficiaire", "Uniquement la date", "Aucune mention"], "L'absence de mention essentielle peut priver l'écrit de la valeur de lettre de change.", 4),
    ("Quelle est la nature de la lettre de change au regard de la qualification d'acte de commerce ?", "Elle est un acte de commerce par la forme", ["Elle est un acte civil toujours", "Elle est un acte administratif", "Elle est un acte de procédure"], "La forme de la lettre de change suffit à la rendre commerciale.", 5),
    ("Quel recours possède le porteur d'une lettre de change impayée contre les signataires ?", "Une action cambiaire", ["Une action en divorce", "Une action en revendication de la nationalité", "Une action en annulation de l'exequatur"], "L'action cambiaire est fondée sur le droit de change.", 5),
    ("Que signifie le mot « cambiaire » ?", "Qui est relatif à la lettre de change et aux effets de commerce", ["Qui est relatif au change des monnaies uniquement", "Qui est relatif aux successions", "Qui est relatif au droit du travail"], "Le droit cambiaire est le droit des effets de commerce.", 5),
    ("Quel effet de commerce suppose l'intervention d'une banque comme tiré ?", "Le chèque", ["Le billet à ordre", "La lettre de change non acceptée", "L'action"], "Le chèque est tiré sur une banque.", 3),
], cat=K, src="sup-comm", region="AF")

mcq(C, "l3dc-mcq3", [
    ("À quoi sert une sûreté ?", "À garantir au créancier le paiement de sa créance", ["À supprimer la dette", "À fixer le prix de la marchandise", "À désigner le juge compétent"], "Une sûreté renforce les chances de paiement du créancier.", 1),
    ("Quelle est la différence essentielle entre sûreté personnelle et sûreté réelle ?", "La première ajoute un débiteur, la seconde affecte un bien précis au paiement", ["La première porte sur un immeuble, la seconde sur une personne", "La première est gratuite, la seconde onéreuse", "La première est facultative, la seconde obligatoire"], "L'engagement d'une personne contre l'affectation d'un bien.", 3),
    ("Laquelle de ces garanties est une sûreté réelle ?", "L'hypothèque", ["Le cautionnement", "La garantie autonome", "La lettre d'intention"], "L'hypothèque affecte un immeuble.", 2),
    ("Sur quel type de bien porte l'hypothèque ?", "Un immeuble", ["Un meuble corporel", "Une créance", "Un chèque"], "L'hypothèque est la sûreté réelle immobilière type.", 2),
    ("Sur quel type de bien porte le gage ?", "Des biens meubles", ["Des immeubles", "Des personnes", "Des marchés publics"], "Le gage porte sur des meubles.", 2),
    ("Que garantit le nantissement ?", "Une créance du créancier, par l'affectation d'un meuble incorporel du débiteur", ["Une créance, par l'affectation d'un immeuble", "Une dette fiscale", "Une dette pénale"], "Il porte sur des biens meubles incorporels comme des créances.", 4),
    ("Que fait la caution lorsqu'elle s'engage ?", "Elle s'engage à payer la dette si le débiteur ne la paie pas", ["Elle paie toujours à la place du débiteur dès l'origine", "Elle perçoit le prix de la marchandise", "Elle remplace le débiteur dans le contrat principal"], "L'engagement de la caution est subsidiaire par nature.", 3),
    ("Le cautionnement est-il, en principe, un contrat accessoire ?", "Oui, il suit le sort de l'obligation garantie", ["Non, il est indépendant de l'obligation garantie", "Non, il est toujours une donation", "Oui, mais uniquement après la faillite"], "L'extinction de la dette garantie éteint le cautionnement.", 4),
    ("En quoi la garantie autonome se distingue-t-elle du cautionnement ?", "Le garant s'engage indépendamment de l'obligation garantie", ["Elle est toujours gratuite", "Elle ne vaut que pour les immeubles", "Elle suit toujours le sort de l'obligation principale"], "L'autonomie est la caractéristique de cette sûreté personnelle.", 5),
    ("Qu'est-ce que le bénéfice de discussion ?", "Le droit de la caution d'exiger que le créancier poursuive d'abord les biens du débiteur", ["Le droit du débiteur de ne pas payer", "Le droit du créancier de saisir les biens de la caution en premier", "Le droit du juge de réduire la dette"], "Il est écarté lorsque la caution est solidaire.", 5),
    ("Qu'est-ce qu'une caution solidaire ?", "Une caution qui ne peut exiger que le créancier poursuive d'abord le débiteur", ["Une caution qui garantit plusieurs dettes", "Une caution salariée", "Une caution qui paie à moitié"], "La solidarité écarte le bénéfice de discussion.", 5),
    ("Qu'est-ce que le droit de rétention ?", "Le droit de garder un bien appartenant au débiteur jusqu'au paiement de la créance", ["Le droit de vendre sans formalité le bien du débiteur", "Le droit de le restituer immédiatement", "Le droit de le détruire"], "Il constitue une garantie de fait pour le créancier.", 4),
    ("Qu'est-ce qu'un privilège en matière de sûretés ?", "Un droit de préférence attaché à la qualité de certaines créances", ["Un droit réel immobilier", "Une garantie bancaire", "Une interdiction de vendre"], "Il permet de passer avant les autres créanciers.", 4),
    ("Qu'est-ce qu'un créancier chirographaire ?", "Un créancier sans garantie particulière", ["Un créancier hypothécaire", "Un créancier gagiste", "Un créancier privilégié"], "Il vient après les créanciers titulaires de sûretés.", 4),
    ("Un créancier titulaire d'une hypothèque est-il, en principe, mieux protégé qu'un créancier chirographaire ?", "Oui, il dispose d'un droit de préférence sur l'immeuble", ["Non, ils sont dans la même situation", "Non, le chirographaire passe avant", "Non, l'hypothèque ne protège pas"], "La sûreté réelle apporte la préférence et le suivi du bien.", 3),
    ("Que permet le droit de suite attaché à une sûreté réelle ?", "Poursuivre le bien entre les mains du tiers acquéreur", ["Se faire payer sans jugement par la caution", "Obtenir la remise de dette", "Transformer la créance en action"], "Le droit de suite suit le bien dans le patrimoine d'autrui.", 5),
    ("Que permet le droit de préférence ?", "Être payé avant les autres créanciers sur le prix du bien affecté", ["Être payé après les autres", "Se faire payer au double", "Éviter tout recours"], "La préférence détermine le rang du créancier.", 4),
    ("Qu'est-ce qu'une lettre d'intention ?", "Un engagement de faire ou de ne pas faire pour soutenir un débiteur", ["Une lettre de change simplifiée", "Un contrat de travail", "Une promesse de vente d'immeuble"], "C'est une sûreté personnelle atypique.", 5),
    ("Qu'est-ce que la cessation des paiements ?", "L'impossibilité de faire face au passif exigible avec l'actif disponible", ["Le fait de ne payer aucune dette", "La baisse du chiffre d'affaires", "Le retard d'une seule échéance"], "La cessation des paiements s'apprécie par comparaison du passif exigible et de l'actif disponible.", 4),
    ("Quel est le but du règlement préventif ?", "Éviter la cessation des paiements et redresser l'entreprise en difficulté", ["Liquider l'entreprise", "Punir le dirigeant", "Transférer l'entreprise à l'État"], "Il est ouvert avant la cessation des paiements.", 3),
    ("Peut-on ouvrir un règlement préventif lorsque l'entreprise est déjà en cessation des paiements ?", "Non, le débiteur ne doit pas être en cessation des paiements", ["Oui, uniquement dans ce cas", "Oui, pour toutes les entreprises", "Oui, uniquement pour les sociétés anonymes"], "C'est une procédure de prévention.", 5),
    ("Quel est le rôle d'un conciliateur ?", "Aider le débiteur et ses créanciers à parvenir à un accord amiable", ["Prononcer la liquidation de l'entreprise", "Saisir les biens du débiteur", "Remplacer le juge"], "La conciliation est une procédure amiable.", 3),
    ("Quel est le but du redressement judiciaire ?", "Permettre la poursuite de l'activité, le maintien de l'emploi et l'apurement du passif", ["La vente immédiate de tous les biens", "La dissolution de l'entreprise", "La punition des associés"], "Il vise la survie de l'entreprise viable.", 3),
    ("Quel est le but de la liquidation des biens ?", "Réaliser l'actif du débiteur pour payer ses créanciers", ["Poursuivre l'activité à tout prix", "Restructurer le capital", "Augmenter le capital"], "Elle est ouverte lorsque le redressement est impossible.", 3),
    ("Quand ouvre-t-on en principe une liquidation des biens plutôt qu'un redressement judiciaire ?", "Quand la situation est irrémédiablement compromise", ["Quand l'entreprise a des bénéfices", "Quand l'entreprise est jeune", "Quand l'entreprise a un seul client"], "L'impossibilité d'un redressement conduit à la liquidation.", 4),
    ("Qu'est-ce qu'un concordat de redressement ?", "Un accord entre le débiteur et ses créanciers pour régler les dettes et poursuivre l'activité", ["Un jugement de condamnation pénale", "Un contrat de vente du fonds", "Une saisie-vente"], "Il est homologué par le tribunal.", 4),
    ("Que signifie la suspension des poursuites individuelles ?", "Après le jugement d'ouverture, les créanciers ne peuvent plus agir seuls contre le débiteur", ["Les créanciers sont tous payés", "Le débiteur ne peut plus travailler", "Les poursuites sont étendues à toute la famille"], "La procédure collective met les créanciers dans une situation d'égalité.", 4),
    ("Qu'est-ce que la masse des créanciers ?", "Le groupement de ceux dont la créance est antérieure au jugement d'ouverture", ["Le groupe des salariés seulement", "Les créanciers d'une seule banque", "Les créanciers nés après le jugement"], "La masse permet une action collective.", 4),
    ("Pourquoi les créanciers sont-ils regroupés dans une procédure collective ?", "Pour traiter collectivement le passif et assurer l'égalité entre eux, sous réserve des préférences", ["Pour que le plus rapide soit payé en premier", "Pour exonérer le débiteur de toute dette", "Pour supprimer le juge"], "La discipline collective remplace la course individuelle aux poursuites.", 4),
    ("Un créancier titulaire d'une sûreté réelle perd-il toute préférence en procédure collective ?", "Non, son rang de préférence est en principe maintenu, avec des aménagements", ["Oui, toujours", "Oui, s'il est une banque", "Oui, s'il est étranger"], "Les sûretés conservent un effet, selon des règles de classement des créanciers.", 5),
    ("Qui peut demander l'ouverture d'une procédure collective ?", "Le débiteur ou un créancier, selon les cas", ["Un voisin du débiteur", "Un candidat aux élections", "Un arbitre"], "La demande peut émaner du débiteur ou d'un créancier.", 4),
    ("Quelle juridiction prononce en principe l'ouverture d'une procédure collective ?", "La juridiction compétente en matière commerciale", ["Le conseil des ministres de l'OHADA", "L'ERSUMA", "La CCJA en premier ressort"], "Le tribunal compétent statue par jugement.", 3),
    ("La procédure collective s'applique-t-elle aux commerçants et aux sociétés commerciales ?", "Oui, entre autres débiteurs relevant du droit OHADA", ["Non, jamais", "Non, seulement aux associations", "Non, seulement aux particuliers"], "Les entreprises en difficulté sont le public principal des procédures collectives.", 3),
    ("Qu'est-ce qu'un titre exécutoire ?", "Un acte qui permet de poursuivre l'exécution forcée sans autre autorisation", ["Un acte qui permet de se défendre", "Un acte qui supprime la dette", "Un acte réservé aux étrangers"], "Une décision de justice définitive est un exemple de titre exécutoire.", 2),
    ("Lequel de ces actes peut constituer un titre exécutoire ?", "Une décision de justice qui a force exécutoire", ["Une facture", "Un devis", "Une lettre de relance"], "Un document privé non homologué ne vaut pas titre exécutoire.", 3),
    ("Une facture impayée constitue-t-elle à elle seule un titre exécutoire ?", "Non, elle doit être confirmée par une décision ou un titre reconnu", ["Oui, toujours", "Oui, en matière commerciale", "Oui, si elle est signée"], "Le créancier doit obtenir un titre exécutoire, par exemple par injonction de payer.", 4),
    ("Qu'est-ce que l'exécution forcée ?", "Le moyen légal de contraindre un débiteur à exécuter son obligation", ["Une mesure disciplinaire", "Un arbitrage", "Une conciliation amiable"], "Elle ne s'exerce pas sans titre exécutoire.", 2),
    ("Quel est le rôle de l'huissier de justice dans l'exécution forcée ?", "Procéder aux actes de signification et aux saisies", ["Juger le litige", "Garantir la dette", "Défendre le débiteur"], "Il est l'agent d'exécution.", 2),
    ("À quoi sert la saisie conservatoire ?", "À rendre un bien indisponible pour préserver le droit du créancier", ["À vendre immédiatement le bien", "À annuler la dette", "À rendre le bien au débiteur"], "Elle est une mesure de précaution.", 3),
    ("Quelle différence y a-t-il entre saisie conservatoire et saisie-vente ?", "La première bloque seulement le bien, la seconde mène à sa vente", ["La première mène à la vente, la seconde bloque seulement", "Aucune", "La première vise les personnes, la seconde les sociétés"], "La saisie-vente suppose un titre exécutoire.", 4),
    ("Que vise la saisie-attribution ?", "Les sommes d'argent que des tiers doivent au débiteur", ["Les immeubles du débiteur", "Les meubles corporels du débiteur", "Les actions du débiteur"], "Le créancier se fait attribuer la créance saisie.", 4),
    ("Qui est le tiers saisi dans une saisie-attribution ?", "La personne qui doit des sommes au débiteur, comme une banque", ["Le juge", "L'huissier", "Le créancier"], "Le tiers saisi détient les sommes du débiteur.", 4),
    ("Que vise la saisie-vente ?", "Les biens meubles corporels du débiteur", ["Les immeubles du débiteur", "Le fonds de commerce uniquement", "Le capital social"], "Les biens saisis sont vendus aux enchères.", 3),
    ("Que vise la saisie immobilière ?", "Un immeuble du débiteur", ["Un meuble corporel", "Une créance sur un tiers", "Une marque"], "La vente forcée suit des règles spécifiques.", 3),
    ("Qu'est-ce qu'une procédure d'injonction de payer ?", "Une procédure simplifiée pour recouvrer une créance certaine, liquide et exigible", ["Une procédure d'arbitrage", "Une procédure de saisie immobilière", "Une procédure pénale"], "Elle permet d'obtenir rapidement une ordonnance exécutoire.", 4),
    ("Qu'est-ce qu'une créance certaine, liquide et exigible ?", "Une créance dont l'existence est établie, le montant déterminé et le paiement échu", ["Une créance sans débiteur", "Une créance encore conditionnelle", "Une créance éteinte"], "Ces trois qualités conditionnent notamment l'injonction de payer.", 4),
    ("Peut-on saisir librement les biens d'une personne morale de droit public ?", "Non, elles bénéficient d'une immunité d'exécution", ["Oui, toujours", "Oui, si le créancier est étranger", "Oui, si le créancier est une banque"], "L'immunité d'exécution protège les personnes publiques.", 5),
    ("Qu'est-ce qu'un bien insaisissable ?", "Un bien que la loi protège contre la saisie par les créanciers", ["Un bien sans valeur", "Un bien situé à l'étranger", "Un bien déjà vendu"], "La loi protège par exemple certains biens nécessaires à la vie.", 3),
    ("Qu'est-ce que la saisie des rémunérations ?", "Une saisie portant sur une fraction du salaire du débiteur", ["Une saisie de tout le salaire sans limite", "Une saisie du capital de l'employeur", "Une saisie de l'immeuble de l'employeur"], "Seule une partie est saisissable.", 3),
    ("Pourquoi une partie seulement du salaire est-elle saisissable ?", "Pour laisser au salarié et à sa famille de quoi subsister", ["Pour faciliter la fraude", "Pour que l'employeur reste propriétaire du salaire", "Pour imposer le travail"], "Le salaire a un caractère alimentaire.", 4),
    ("Qu'est-ce que le commandement de payer ?", "L'acte par lequel l'huissier somme le débiteur de payer avant la saisie", ["Un jugement de condamnation", "Une décision d'arbitrage", "Un acte de caution"], "Il précède certaines saisies.", 3),
    ("Qu'est-ce que l'arbitrage ?", "Un mode privé de règlement des litiges par des arbitres choisis par les parties", ["Un recours devant la Cour suprême", "Une réclamation à l'inspecteur du travail", "Une mesure d'exécution forcée"], "Les parties soustraient leur litige au juge étatique.", 2),
    ("L'arbitrage est-il fondé sur la volonté des parties ?", "Oui, il repose sur une convention d'arbitrage", ["Non, il est imposé par la loi dans tous les litiges", "Non, il est toujours décidé par le juge", "Non, il est ordonné par le procureur"], "Sans accord des parties, pas d'arbitrage.", 2),
    ("Quelle est la différence entre clause compromissoire et compromis ?", "La clause est conclue avant le litige, le compromis après sa naissance", ["La clause est conclue après le litige, le compromis avant", "Chacune est conclue par le juge", "Chacune est une sentence"], "L'une prévoit l'arbitrage pour l'avenir, l'autre pour un litige déjà né.", 3),
    ("Dans quel document figure habituellement une clause compromissoire ?", "Dans le contrat principal entre les parties", ["Dans la loi", "Dans la décision du juge", "Dans le registre du commerce"], "La clause est insérée au contrat.", 3),
    ("Qu'est-ce qu'une sentence arbitrale ?", "La décision rendue par le tribunal arbitral qui tranche le litige", ["Un acte de procédure", "Un projet de loi", "Un acte notarié"], "Elle a, en principe, autorité de chose jugée.", 3),
    ("Une sentence arbitrale a-t-elle autorité de chose jugée ?", "Oui, dès qu'elle est rendue", ["Non, jamais", "Non, il faut un vote", "Oui, mais seulement pour les mineurs"], "Elle est obligatoire pour les parties.", 4),
    ("À quoi sert l'exequatur ?", "À conférer force exécutoire à une sentence arbitrale", ["À annuler une sentence", "À nommer un arbitre", "À fixer les honoraires des arbitres"], "L'exequatur permet l'exécution forcée de la sentence.", 4),
    ("Peut-on exécuter forcément une sentence arbitrale sans exequatur ?", "Non, l'exequatur est en principe nécessaire", ["Oui, toujours", "Oui, par simple lettre", "Oui, par le seul arbitre"], "La sentence n'a pas par elle-même force exécutoire.", 5),
    ("Quelle est la principale caractéristique de la procédure arbitrale par rapport au procès étatique ?", "La liberté des parties de choisir les arbitres et la procédure", ["Elle est publique par principe", "Elle est gratuite", "Elle est dirigée par le procureur"], "L'arbitrage privilégie la souplesse et la confidentialité.", 4),
    ("Quel principe fondamental doit respecter la procédure arbitrale ?", "Le principe du contradictoire et l'égalité des parties", ["La prévalence de l'une des parties", "Le secret du dossier pour l'une des parties", "L'interdiction de toute défense"], "Le respect des droits de la défense reste exigé.", 4),
    ("Peut-on, en principe, compromettre sur toute question, y compris l'état des personnes ?", "Non, l'arbitrage est réservé aux droits dont les parties ont la libre disposition", ["Oui, sur toute question", "Oui, uniquement sur l'état des personnes", "Oui, uniquement sur le droit pénal"], "L'arbitrabilité suppose des droits disponibles.", 5),
    ("Qu'est-ce que le principe de compétence-compétence ?", "L'arbitre peut décider lui-même s'il est compétent", ["Le juge étatique décide seul de la compétence de l'arbitre", "Le tribunal arbitral décide de la compétence du juge", "L'État désigne l'arbitre"], "Le tribunal arbitral statue sur sa propre compétence.", 5),
    ("Qu'est-ce que la médiation ?", "Un mode amiable où un tiers neutre aide les parties à trouver une solution, sans la leur imposer", ["Un jugement imposé", "Une sentence arbitrale", "Un acte d'exécution forcée"], "Le médiateur facilite la discussion, il ne tranche pas.", 3),
    ("Quelle différence y a-t-il entre médiation et arbitrage ?", "Le médiateur propose ou facilite, l'arbitre tranche et rend une décision obligatoire", ["Le médiateur tranche, l'arbitre facilite", "Il n'y a aucune différence", "Le médiateur est juge de l'État"], "L'arbitre rend une sentence ; le médiateur aide à un accord.", 4),
    ("Qu'est-ce que la comptabilité ?", "Un système d'enregistrement et de présentation de l'information financière d'une entreprise", ["Un système de vente de marchandises", "Un système d'élection", "Un système judiciaire"], "Elle sert à connaître la situation et les résultats.", 1),
    ("Que décrit le bilan ?", "La situation patrimoniale de l'entreprise à une date donnée", ["Les résultats d'une journée", "Les projets de l'entreprise", "La liste des clients seulement"], "Il oppose l'actif au passif.", 2),
    ("Quelle égalité fondamentale vérifie le bilan ?", "Le total de l'actif est égal au total du passif", ["L'actif est toujours supérieur au passif", "Le passif est toujours supérieur à l'actif", "Les charges sont égales aux produits"], "Les emplois correspondent aux ressources.", 3),
    ("Que montre le compte de résultat ?", "La différence entre les produits et les charges de l'exercice", ["La situation à une date donnée", "Le montant des apports", "La liste des immobilisations"], "Elle permet de calculer le bénéfice ou la perte.", 2),
    ("Que signifie un résultat bénéficiaire ?", "Les produits de l'exercice dépassent les charges", ["Les charges dépassent les produits", "Les dettes sont nulles", "Le capital augmente automatiquement"], "Bénéfice = produits − charges.", 2),
    ("Que signifie un résultat déficitaire ?", "Les charges de l'exercice dépassent les produits", ["Les produits dépassent les charges", "Il n'y a pas d'opération", "L'actif est toujours nul"], "La perte résulte d'un excédent de charges.", 2),
    ("Que traduit la comptabilité en partie double ?", "Chaque opération est enregistrée au débit d'un compte et au crédit d'un autre pour le même montant", ["Chaque opération est enregistrée deux fois dans le même compte", "Chaque opération est enregistrée seulement au crédit", "Chaque opération est enregistrée seulement au débit"], "L'équilibre débit-crédit est le principe de base.", 3),
    ("Que signifie le principe de prudence en comptabilité ?", "Ne pas anticiper les profits probables mais tenir compte des pertes et risques probables", ["Anticiper tous les profits", "Ne comptabiliser aucune dette", "Cacher les pertes"], "La prudence évite de présenter une situation trop favorable.", 4),
    ("Que signifie le principe de continuité d'exploitation ?", "Les comptes sont établis dans l'hypothèse que l'entreprise poursuivra son activité", ["L'entreprise ne peut jamais fermer", "Les comptes ne sont jamais arrêtés", "L'entreprise est vendue chaque année"], "C'est une convention comptable fondamentale.", 4),
    ("Que signifie le principe d'indépendance des exercices ?", "Chaque exercice doit recevoir les charges et produits qui le concernent", ["Les exercices ne sont jamais comparés", "Les exercices sont fusionnés", "L'exercice est supprimé"], "Les opérations sont rattachées à l'exercice auquel elles se rapportent.", 5),
    ("Qu'est-ce qu'une immobilisation ?", "Un bien durable destiné à rester dans l'entreprise, par exemple un bâtiment", ["Une marchandise destinée à être vendue rapidement", "Une dette à court terme", "Un impôt"], "Elle se distingue des stocks.", 2),
    ("Qu'est-ce qu'un stock ?", "Des marchandises ou matières destinées à être vendues ou consommées", ["Un bâtiment de l'entreprise", "Une dette envers une banque", "Un capital apporté"], "Le stock fait partie de l'actif circulant.", 2),
    ("Un amortissement est-il un décaissement d'argent ?", "Non, c'est une charge calculée sans sortie de trésorerie à ce titre", ["Oui, toujours", "Oui, vers l'État", "Oui, vers le commissaire aux comptes"], "L'amortissement n'entraîne pas à lui seul de sortie d'argent.", 5),
    ("Que sont les capitaux propres ?", "Les ressources appartenant aux propriétaires de l'entreprise, comme le capital et les réserves", ["Les dettes envers les fournisseurs", "Les créances sur les clients", "Les stocks"], "Ils figurent au passif.", 3),
    ("Où figure une dette envers un fournisseur ?", "Au passif du bilan", ["À l'actif du bilan", "Au compte de résultat comme produit", "Dans les capitaux propres"], "Une dette est une ressource d'emprunt.", 2),
    ("Où figure le montant dû par les clients ?", "À l'actif du bilan, comme créance", ["Au passif comme capital", "Au compte de résultat comme charge", "Parmi les capitaux propres"], "Les créances sont des droits de l'entreprise.", 2),
    ("L'achat de marchandises destinées à la revente est-il comptabilisé comme un produit ?", "Non, c'est une charge, ou une variation de stock", ["Oui, comme un produit", "Oui, comme un capital", "Oui, comme une subvention"], "L'achat est un coût, la vente un produit.", 3),
    ("Le SYSCOHADA a-t-il pour objectif d'harmoniser la comptabilité des entreprises des États de l'OHADA ?", "Oui, il fournit un cadre comptable commun", ["Non, chaque entreprise choisit son cadre", "Non, il ne vise que les banques centrales", "Non, il vise seulement les particuliers"], "L'harmonisation comptable accompagne l'harmonisation du droit des affaires.", 3),
    ("À quoi sert un plan comptable ?", "À fournir une liste normalisée de comptes pour enregistrer les opérations", ["À fixer le prix des produits", "À désigner les dirigeants", "À organiser les élections"], "Il uniformise la présentation des comptes.", 2),
    ("Quels états financiers annuels une entreprise établit-elle de façon générale ?", "Le bilan, le compte de résultat, le tableau des flux de trésorerie et l'annexe", ["Seulement le bilan", "Seulement la liste des clients", "Seulement le registre du commerce"], "Les états financiers donnent une image fidèle de la situation.", 4),
    ("À quoi sert l'annexe aux états financiers ?", "À compléter et commenter les informations du bilan et du compte de résultat", ["À remplacer le bilan", "À fixer le prix des marchandises", "À désigner les administrateurs"], "Elle donne des explications utiles aux lecteurs.", 3),
    ("Qu'est-ce que le tableau des flux de trésorerie ?", "L'état qui retrace les entrées et sorties de liquidités sur l'exercice", ["L'état des créanciers", "L'état des brevets", "L'état des immobilisations seulement"], "Il montre l'origine et l'emploi de la trésorerie.", 4),
    ("Pourquoi la comptabilité est-elle une obligation pour le commerçant ?", "Pour suivre l'activité, informer les tiers et servir de moyen de preuve", ["Pour limiter la concurrence", "Pour supprimer l'impôt", "Pour remplacer le registre du commerce"], "La comptabilité remplit plusieurs fonctions : gestion, information, preuve.", 3),
    ("Qu'est-ce que la comptabilité générale ?", "L'enregistrement des opérations externes de l'entreprise pour établir ses états financiers", ["Le calcul des coûts de revient internes uniquement", "La comptabilité de l'État", "La comptabilité des associations uniquement"], "Elle se distingue de la comptabilité analytique.", 3),
    ("Que mesure la comptabilité analytique, de façon générale ?", "Les coûts internes et la rentabilité des activités ou produits", ["Les impôts dus", "Les dettes de l'État", "Les salaires de l'État"], "Elle sert à la gestion interne.", 4),
    ("À quoi sert la provision pour risques ?", "Prendre en compte par prudence une charge probable dont le montant ou la date est incertain", ["Constater un gain probable", "Rembourser un emprunt", "Distribuer un dividende"], "La provision anticipe une perte probable.", 4),
    ("Dans le fonctionnement des comptes, que signifie « débiter » un compte ?", "Inscrire un montant dans la colonne de gauche du compte", ["Inscrire dans la colonne de droite", "Supprimer le compte", "Fusionner deux comptes"], "Le débit est à gauche, le crédit à droite.", 2),
], cat="Comptabilité (niveau général) et sûretés, procédures, exécution, arbitrage", src="sup-comm", region="AF")


mcq(C, "l3dx-mcq4", [
    ("Un salarié est licencié sans que la lettre indique de motif précis. Dans un système protecteur, quelle est la conséquence habituelle ?", "Le licenciement risque d'être jugé sans cause réelle et sérieuse", ["Il est valable car l'employeur n'a pas à se justifier", "Il devient une démission", "Il est automatiquement converti en CDD"], "L'énoncé du motif est une garantie pour le salarié et pour le contrôle du juge.", 5),
    ("Quelle est la principale différence entre la grève et le lock-out ?", "La grève est un arrêt du travail par les salariés, le lock-out une fermeture par l'employeur", ["La grève est décidée par l'employeur, le lock-out par les salariés", "Ce sont deux sanctions disciplinaires", "Ce sont deux formes de licenciement"], "Ce sont deux modes d'action opposés dans un conflit collectif.", 4),
    ("Pourquoi un syndicat peut-il agir en justice pour défendre l'intérêt collectif de la profession ?", "Parce qu'il a pour objet la défense des intérêts collectifs de ses membres et de la profession", ["Parce qu'il remplace le juge du travail", "Parce qu'il est un organe de l'État", "Parce qu'il est un employeur"], "Le syndicat dispose d'une capacité d'agir pour l'intérêt collectif.", 5),
    ("Que signifie la notion de « représentativité » d'un syndicat ?", "Son aptitude légale à représenter les salariés dans la négociation collective", ["Son appartenance à un parti politique", "Sa fortune", "Son ancienneté seulement"], "La représentativité conditionne notamment la négociation des accords.", 5),
    ("En droit du travail, qu'est-ce qu'un usage d'entreprise ?", "Une pratique constante, générale et fixe suivie par l'employeur à l'égard du personnel", ["Une loi votée par l'assemblée", "Un jugement du tribunal", "Une sanction disciplinaire"], "Un tel usage peut créer des droits pour les salariés tant qu'il n'est pas dénoncé régulièrement.", 5),
    ("En droit français, un employeur peut-il supprimer un avantage résultant d'un usage d'entreprise sans aucune formalité ?", "Non, il doit en principe le dénoncer régulièrement, notamment en informant les intéressés", ["Oui, immédiatement et sans prévenir", "Oui, en prévenant seulement le juge", "Oui, en prévenant l'État"], "La dénonciation régulière respecte une procédure d'information préalable.", 5),
    ("Quel est le rôle de la hiérarchie des sources en droit du travail ?", "Déterminer quelle norme l'emporte en cas de conflit entre loi, convention collective et contrat", ["Fixer le salaire de chaque salarié", "Choisir le juge compétent", "Nommer les inspecteurs du travail"], "Elle organise les rapports entre normes de niveaux différents.", 4),
    ("Un contrat de travail peut-il valablement prévoir des règles moins favorables que la convention collective applicable ?", "Non, en principe il ne peut y déroger dans un sens défavorable au salarié", ["Oui, toujours", "Oui, si l'employeur le souhaite", "Oui, si le salarié est cadre"], "Le contrat peut améliorer mais non réduire les droits conventionnels, sauf exceptions.", 5),
    ("Quel est l'effet d'une clause du contrat de travail contraire à une règle d'ordre public de protection du salarié ?", "Elle est en principe nulle", ["Elle prime sur la loi", "Elle est valable pour un temps limité", "Elle devient obligatoire pour l'employeur"], "L'ordre public social limite la liberté contractuelle.", 5),
    ("Qu'est-ce que l'ordre public social ?", "L'ensemble des règles protectrices du salarié auxquelles on ne peut déroger dans un sens défavorable", ["Les règles de l'État sur la sécurité publique", "Les règles de la procédure pénale", "Les règles de la hiérarchie militaire"], "Il fonde l'indisponibilité de certains droits des salariés.", 5),
    ("Dans un redressement judiciaire, que devient en principe le contrat de travail des salariés lors de la poursuite de l'activité ?", "Il se poursuit, la procédure collective ne le rompt pas par elle-même", ["Il est rompu automatiquement", "Il est suspendu pour toujours", "Il est transféré à l'État"], "Ce sont des licenciements motivés qui peuvent éventuellement intervenir ensuite.", 5),
    ("Dans la procédure collective, comment les salaires impayés sont-ils traités ?", "Ils bénéficient d'un traitement privilégié par rapport aux créanciers ordinaires", ["Ils passent après tous les autres créanciers", "Ils sont supprimés", "Ils sont convertis en actions"], "Le privilège des salaires protège les travailleurs.", 5),
    ("Quelle différence y a-t-il entre société et association sur le plan du but ?", "La société vise à partager des bénéfices, l'association poursuit un autre but", ["L'association vise toujours des bénéfices à partager, la société non", "Aucune différence", "La société est publique, l'association privée"], "Le but lucratif distingue la société de l'association.", 4),
    ("Dans une SARL, quel est le régime de la cession de parts à un tiers étranger à la société ?", "La cession est en principe soumise à des conditions d'agrément", ["Toujours librement et sans formalité", "Jamais, sous aucun prétexte", "Uniquement par décision du tribunal de commerce"], "Le caractère personnel de la SARL justifie un encadrement de la cession.", 5),
    ("Les actions d'une société anonyme sont-elles, en principe, librement négociables ?", "Oui, sauf stipulations légales ou statutaires encadrant leur cession", ["Non, jamais", "Non, seulement entre salariés", "Non, seulement avec l'accord du juge"], "La négociabilité est un trait de la société de capitaux.", 4),
    ("Que doit contenir en principe l'acte constitutif d'une société, de façon générale ?", "Les statuts précisant notamment la forme, l'objet, le siège, la durée et le capital", ["Seulement le nom du notaire", "Seulement la date de naissance du gérant", "Seulement le prix des marchandises"], "Les statuts fixent le cadre de fonctionnement de la société.", 3),
    ("Un tiers peut-il se prévaloir d'une société non immatriculée comme d'une personne morale ?", "Non, avant l'immatriculation la société n'a pas la personnalité morale", ["Oui, dès la signature des statuts", "Oui, dès la première vente", "Oui, par simple annonce"], "L'immatriculation donne naissance à la personne morale.", 5),
    ("Quelle différence existe-t-il entre insolvabilité et cessation des paiements ?", "La cessation vise la trésorerie, l'insolvabilité l'insuffisance globale du patrimoine", ["Ce sont exactement les mêmes notions", "La cessation concerne les particuliers, l'insolvabilité les sociétés", "L'insolvabilité est un mode de preuve"], "Une entreprise peut avoir un patrimoine suffisant mais être en cessation des paiements faute de liquidités.", 5),
    ("Quel est l'effet de l'immunité d'exécution d'une collectivité publique ?", "Ses biens ne peuvent pas être saisis par ses créanciers selon le droit commun", ["Elle est dispensée de payer ses dettes", "Elle ne peut jamais être condamnée", "Elle est dispensée de rendre des comptes"], "L'immunité d'exécution n'éteint pas la dette : elle protège les biens contre les saisies.", 5),
    ("Un créancier saisit-il en principe le bien d'un tiers pour payer la dette du débiteur ?", "Non, la saisie porte sur les biens du débiteur", ["Oui, sur tous les biens de sa famille", "Oui, sur tous les biens de ses voisins", "Oui, sur les biens de l'huissier"], "Le gage général des créanciers est le patrimoine du débiteur.", 3),
    ("Qu'est-ce que le gage général des créanciers ?", "Le droit pour tous les créanciers de se payer sur l'ensemble du patrimoine du débiteur", ["Une hypothèque sur un immeuble précis", "Un gage portant sur un meuble précis", "Une caution donnée par un tiers"], "Les créanciers chirographaires comptent sur ce gage général.", 4),
    ("Quel est l'effet de la clause compromissoire sur la compétence du juge étatique ?", "Elle fait obstacle, en principe, à la saisine du juge étatique du fond pour le litige visé", ["Elle rend le juge compétent exclusivement", "Elle supprime le droit d'agir en justice pour toujours", "Elle oblige le juge à désigner un notaire"], "Le juge saisi se déclare en principe incompétent si le tribunal arbitral est valablement saisi.", 5),
    ("Quelles sont les voies de recours en principe ouvertes contre une sentence arbitrale ?", "Un recours en annulation pour des cas limités, et non l'appel au fond", ["L'appel au fond devant la Cour suprême", "L'appel au fond devant l'arbitre", "Aucun recours imaginable"], "Le contrôle judiciaire de la sentence est limité.", 5),
    ("Une sentence arbitrale peut-elle être réformée sur le fond par le juge étatique ?", "En principe non, le juge ne réexamine pas le fond du litige", ["Oui, systématiquement", "Oui, par la CCJA seule", "Oui, par l'huissier"], "Le juge de l'annulation ne rejuge pas l'affaire.", 5),
    ("Dans la tenue des comptes, que signifie « créditer » un compte ?", "Inscrire un montant dans la colonne de droite du compte", ["Inscrire un montant dans la colonne de gauche", "Supprimer un montant", "Reporter un solde"], "Le crédit est à droite, le débit à gauche.", 2),
    ("Une entreprise reçoit d'un client une avance sur une commande future. Comment la comptabilise-t-elle, en principe ?", "Comme une dette envers le client tant que la livraison n'est pas faite", ["Comme un produit définitif immédiat", "Comme une charge", "Comme un capital"], "Une avance reçue crée une obligation de livrer.", 5),
    ("Qu'est-ce que la valeur nette comptable d'une immobilisation ?", "Sa valeur d'origine diminuée des amortissements cumulés", ["Sa valeur de marché", "Sa valeur d'origine augmentée des amortissements", "Le prix de vente espéré"], "La valeur nette tient compte de la dépréciation constatée.", 5),
    ("Un commerçant qui tient sa comptabilité sans pièces justificatives respecte-t-il le principe de justification des écritures ?", "Non, chaque écriture doit en principe reposer sur une pièce justificative", ["Oui, les pièces sont inutiles", "Oui, si le montant est faible", "Oui, si le comptable est diplômé"], "Les pièces justificatives garantissent la fiabilité de la comptabilité.", 4),
], cat="Compléments transversaux (travail, sociétés, procédures, comptabilité)", src="sup-comm", region="AF")
